# try.sh — a shell (or one command) with HOME and CLAUDE_CONFIG_DIR in
# t/try, filled with sample data, and the freshly built csm first in PATH.
# Nothing outside t/try is read or written by csm started from there.
#
# Usage: tools/try.sh [-r] [-f] [COMMAND...]
#   -r  make the sample data anew (t/try is deleted first)
#   -f  pretend Claude Code is not running (changes are not blocked)

ROOT=$(cd "$(dirname "$0")/.." && pwd -P)
TRY=$ROOT/t/try
RESET=0
FAKE=0

while getopts rf OPT
do
	case $OPT
	in
	r)
		RESET=1
		;;
	f)
		FAKE=1
		;;
	*)
		echo "usage: tools/try.sh [-r] [-f] [COMMAND...]" >&2
		exit 2
		;;
	esac
done
shift $((OPTIND - 1))

HOME=$TRY/home
CLAUDE_CONFIG_DIR=$HOME/.claude
PROJ=$CLAUDE_CONFIG_DIR/projects

# The session directory name of a path, as Claude Code makes it (one "-"
# per character; the sample paths have no characters outside the BMP).
enc() {
	printf '%s' "$1" | LC_ALL=en_US.UTF-8 sed 's/[^A-Za-z0-9]/-/g'
}

# session PROJECT FILE COUNT PROMPT [BRANCH] — a session file with COUNT
# exchanges, the first prompt PROMPT, started a day earlier per file.
session() {
	DIR=$PROJ/$(enc "$1")
	mkdir -p "$DIR"
	awk -v cwd="$1" -v n="$3" -v prompt="$4" -v branch="${5:-main}" \
	    -v day="$(printf '%s' "$2" | tr -cd 0-9)" 'BEGIN {
		printf "{\"type\":\"permission-mode\",\"permissionMode\":\"default\"}\n"
		for (i = 0; i < n; i++) {
			text = i == 0 ? prompt : "next step " i
			printf "{\"type\":\"user\",\"cwd\":\"%s\",\"gitBranch\":\"%s\",\"timestamp\":\"2026-10-%02dT09:%02d:00Z\",\"message\":{\"role\":\"user\",\"content\":\"%s\"}}\n", cwd, branch, 27 - day % 20, i % 60, text
			printf "{\"type\":\"assistant\",\"cwd\":\"%s\",\"gitBranch\":\"%s\",\"message\":{\"role\":\"assistant\",\"content\":[{\"type\":\"text\",\"text\":\"Done.\"}]}}\n", cwd, branch
		}
	}' > "$DIR/$2.jsonl"
}

make_data() {
	DEV=$HOME/Developer
	mkdir -p "$PROJ" "$DEV/repo/sub" "$DEV/Zażółć gęślą"
	session "$DEV/repo" s1 3 "Fix the parser"
	session "$DEV/repo" s2 12 "Napraw błąd w parserze" feature/parser
	# A long session: -s and the details panel read it in full.
	session "$DEV/repo" s3 20000 "A long conversation"
	mkdir -p "$PROJ/$(enc "$DEV/repo")/memory"
	echo "Notes" > "$PROJ/$(enc "$DEV/repo")/memory/MEMORY.md"
	session "$DEV/repo/sub" s4 2 "Work in a subdirectory"
	session "$DEV/Zażółć gęślą" s5 4 "日本語 i emoji 🙂 — szerokie znaki"
	# A prompt with an escape sequence: it must not colour the terminal.
	# awk -v and the shell both eat a backslash, hence four.
	session "$DEV/Zażółć gęślą" s6 1 "red \\\\u001b[31mtext\\\\u001b[0m and a\\\\ttab"
	session "$HOME/Old/gone" s7 2 "This project was deleted"
	session /Volumes/csm-missing/project s8 1 "On a volume that is not mounted"
	mkdir -p "$PROJ/-x-unknown/memory"
	I=1
	while [ $I -le 30 ]
	do
		N=$(printf '%02d' $I)
		mkdir -p "$DEV/p$N"
		session "$DEV/p$N" s$I $((I % 5 + 1)) "Project $N, first prompt"
		I=$((I + 1))
	done
	printf '{\n  "projects": {\n    "%s": {\n      "allowedTools": []\n    },\n    "%s": {}\n  }\n}\n' \
	    "$DEV/repo" "$HOME/Old/gone" > "$CLAUDE_CONFIG_DIR/.claude.json"
}

if [ $RESET -eq 1 ]
then
	rm -rf "$TRY"
fi
if [ ! -d "$PROJ" ]
then
	make_data
fi
# Shell start files, so zsh does not run its first-time setup.
if [ ! -f "$HOME/.zshrc" ]
then
	echo "PROMPT='(csm try) %~ %# '" > "$HOME/.zshrc"
	echo "PS1='(csm try) \\w \\$ '" > "$HOME/.bashrc"
fi

PATH=$ROOT:$PATH
export HOME CLAUDE_CONFIG_DIR PATH
if [ $FAKE -eq 1 ]
then
	CSM_CLAUDE_PROCESS=csm-no-such-process
	export CSM_CLAUDE_PROCESS
fi
cd "$HOME" || exit 1
if [ $# -eq 0 ]
then
	echo "HOME=$HOME — exit returns to your own shell."
	exec "${SHELL:-/bin/sh}"
fi
exec "$@"
